function showTutorialStep(step = 0) {
  ui.tutorialStep = Math.max(0, Math.min(step, tutorialSteps.length - 1));
  const current = tutorialSteps[ui.tutorialStep];
  const progress = ((ui.tutorialStep + 1) / tutorialSteps.length) * 100;
