import { createClient } from '@supabase/supabase-js';

const url = import.meta.env.VITE_SUPABASE_URL;
const key = import.meta.env.VITE_SUPABASE_ANON_KEY;

export const supabase = url && key ? createClient(url, key, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: false
  }
}) : null;

export function backendSetupError() {
  return new Error('A conexão com o Supabase não está configurada. Confira o arquivo .env.local e reinicie o app.');
}

export function readableSupabaseError(error) {
  const message = error?.message || '';
  if (/Invalid API key|Invalid JWT|JWT/i.test(message)) return 'A chave pública do Supabase está incorreta. Confira VITE_SUPABASE_ANON_KEY.';
  if (/Failed to fetch|NetworkError|fetch/i.test(message)) return 'Não foi possível conectar ao Supabase. Confira sua internet e a URL do projeto.';
  if (/relation .* does not exist|schema cache/i.test(message)) return 'As tabelas do RPG Hub ainda não foram criadas. Execute supabase/schema.sql no SQL Editor do projeto.';
  if (/function .* does not exist|Could not find the function/i.test(message)) return 'As funções do RPG Hub ainda não foram configuradas. Execute supabase/schema.sql no SQL Editor do projeto.';
  if (/Anonymous sign-ins are disabled|anonymous sign-ins/i.test(message)) return 'Ative o acesso anônimo em Supabase → Authentication → Sign In / Providers → Anonymous.';
  return message || 'Não foi possível concluir a operação. Tente novamente.';
}

import { supabase, backendSetupError, readableSupabaseError } from './supabase.js';

const SESSION_KEY = 'rpghub-online-session';

export class SupabaseRepository {
  constructor() {
    this.state = { users: [], currentUserId: null, campaigns: [] };
    this.authUserId = null;
    this.channel = null;
  }

  get user() { return this.state.users.find((item) => item.id === this.state.currentUserId) || null; }
  get campaigns() { return this.state.campaigns; }
  getCampaign(id) { return this.state.campaigns.find((item) => item.id === id); }
  getCharacter(campaign, userId = this.state.currentUserId) { return campaign?.characters?.find((item) => item.userId === userId); }

  async initialize() {
    if (!supabase) throw backendSetupError();
    const { data, error } = await supabase.auth.getSession();
    if (error) throw new Error(readableSupabaseError(error));
    this.authUserId = data.session?.user?.id || null;
    if (this.authUserId && localStorage.getItem(SESSION_KEY) === 'active') {
      const { data: profile, error: profileError } = await supabase.from('profiles').select('id,name,avatar').eq('id', this.authUserId).maybeSingle();
      if (profileError) throw new Error(readableSupabaseError(profileError));
      if (profile) {
        this.state.currentUserId = this.authUserId;
        this.state.users = [profile];
        await this.refreshData();
        this.subscribe();
      }
    }
  }

  async signIn(name) {
    if (!supabase) throw backendSetupError();
    const cleanName = name.trim().slice(0, 24);
    if (!cleanName) throw new Error('Digite um nome de jogador.');
    if (!this.authUserId) {
      const { data, error } = await supabase.auth.signInAnonymously();
      if (error) throw new Error(readableSupabaseError(error));
      this.authUserId = data.user.id;
    }
    const profile = { id: this.authUserId, name: cleanName, avatar: '' };
    const { error } = await supabase.from('profiles').upsert(profile, { onConflict: 'id' });
    if (error) throw new Error(readableSupabaseError(error));
    localStorage.setItem(SESSION_KEY, 'active');
    this.state.currentUserId = this.authUserId;
    this.state.users = [profile];
    await this.refreshData();
    this.subscribe();
    this.notify();
    return profile;
  }

  signOut() {
    // Mantém a identidade anônima neste dispositivo para que desconectar não apague o acesso às campanhas.
    localStorage.removeItem(SESSION_KEY);
    this.state = { users: [], currentUserId: null, campaigns: [] };
    this.notify();
  }

  async refreshData() {
    if (!supabase || !this.state.currentUserId) return;
    const { data: rows, error } = await supabase.from('campaigns').select('id,gm_id,invite_code,members,data,created_at').order('created_at', { ascending: false });
    if (error) throw new Error(readableSupabaseError(error));
    this.state.campaigns = (rows || []).map((row) => this.mapCampaign(row));
    const ids = [...new Set([this.state.currentUserId, ...this.state.campaigns.flatMap((campaign) => campaign.members)])];
    if (ids.length) {
      const { data: profiles, error: profileError } = await supabase.from('profiles').select('id,name,avatar').in('id', ids);
      if (profileError) throw new Error(readableSupabaseError(profileError));
      const byId = new Map((profiles || []).map((profile) => [profile.id, profile]));
      if (!byId.has(this.state.currentUserId)) {
        const own = this.state.users.find((item) => item.id === this.state.currentUserId);
        if (own) byId.set(own.id, own);
      }
      this.state.users = [...byId.values()];
    }
    this.notify();
  }

  mapCampaign(row) {
    const data = row.data || {};
    return {
      ...data,
      id: row.id,
      gmId: row.gm_id,
      inviteCode: row.invite_code,
      members: row.members || [],
      fields: data.fields || [],
      characters: data.characters || [],
      messages: data.messages || [],
      createdAt: row.created_at || data.createdAt
    };
  }

  subscribe() {
    if (!supabase || !this.state.currentUserId) return;
    if (this.channel) supabase.removeChannel(this.channel);
    this.channel = supabase.channel(`rpg-hub-${this.state.currentUserId}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'campaigns' }, () => {
        this.refreshData().catch((error) => console.warn('Não foi possível atualizar as campanhas.', error));
      })
      .subscribe();
  }

  notify() {
    window.dispatchEvent(new CustomEvent('rpg:data-changed'));
  }

  async deleteCampaign(campaignId) {
    const campaign = this.getCampaign(campaignId);
    if (!campaign) throw new Error('Esta campanha não existe mais.');
    if (!this.user || campaign.gmId !== this.user.id) throw new Error('Somente o Mestre pode excluir esta campanha.');
    const { error } = await supabase.from('campaigns').delete().eq('id', campaignId);
    if (error) throw new Error(readableSupabaseError(error));
    this.state.campaigns = this.state.campaigns.filter((item) => item.id !== campaignId);
    this.notify();
  }

  uniqueCode() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    return Array.from({ length: 6 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
  }

  async createCampaign({ name, description, cover, fields }) {
    if (!this.user) throw new Error('Entre na sua conta antes de criar uma campanha.');
    const id = crypto.randomUUID();
    const createdAt = new Date().toISOString();
    const data = {
      name, description, cover, gmName: this.user.name, fields,
      characters: [],
      messages: [{ id: crypto.randomUUID(), userId: 'system', name: 'RPG Hub', role: 'system', text: `A aventura “${name}” começa. O mestre pode compartilhar o código com os jogadores.`, time: Date.now() }]
    };
    for (let attempt = 0; attempt < 4; attempt += 1) {
      const inviteCode = this.uniqueCode();
      const { data: row, error } = await supabase.from('campaigns').insert({
        id, gm_id: this.user.id, invite_code: inviteCode, members: [this.user.id], data, created_at: createdAt
      }).select('id,gm_id,invite_code,members,data,created_at').single();
      if (!error) {
        const campaign = this.mapCampaign(row);
        this.state.campaigns.unshift(campaign);
        this.notify();
        return campaign;
      }
      if (error.code !== '23505' || attempt === 3) throw new Error(readableSupabaseError(error));
    }
    throw new Error('Não foi possível gerar um código de convite. Tente novamente.');
  }

  async joinCampaign(code) {
    const cleanCode = String(code || '').trim().toUpperCase();
    if (!cleanCode) throw new Error('Digite o código de convite.');
    const { data, error } = await supabase.rpc('rpg_join_campaign', { p_code: cleanCode });
    if (error) {
      if (/not found|Código não encontrado/i.test(error.message)) throw new Error('Código não encontrado. Confira com o mestre e tente novamente.');
      throw new Error(readableSupabaseError(error));
    }
    const campaign = this.mapCampaign(data);
    this.state.campaigns = [campaign, ...this.state.campaigns.filter((item) => item.id !== campaign.id)];
    await this.refreshData();
    return this.getCampaign(campaign.id) || campaign;
  }

  async saveCharacter(campaignId, values, portrait) {
    const campaign = this.getCampaign(campaignId);
    if (!campaign) throw new Error('Esta campanha não existe mais.');
    const existing = this.getCharacter(campaign);
    const character = {
      id: existing?.id || crypto.randomUUID(),
      userId: this.state.currentUserId,
      name: values.name || this.user.name,
      values,
      portrait: portrait ?? existing?.portrait ?? ''
    };
    const { data, error } = await supabase.rpc('rpg_save_character', { p_campaign_id: campaignId, p_character: character });
    if (error) throw new Error(readableSupabaseError(error));
    const updated = this.mapCampaign(data);
    this.replaceCampaign(updated);
    return updated.characters.find((item) => item.userId === this.state.currentUserId) || character;
  }

  async sendMessage(campaignId, message) {
    const { data, error } = await supabase.rpc('rpg_send_message', {
      p_campaign_id: campaignId,
      p_message: { text: message.text, type: message.type || 'text', role: message.role || 'player' }
    });
    if (error) throw new Error(readableSupabaseError(error));
    const campaign = this.getCampaign(campaignId);
    if (campaign && data) campaign.messages.push(data);
    this.notify();
  }

  replaceCampaign(updated) {
    this.state.campaigns = this.state.campaigns.map((item) => item.id === updated.id ? updated : item);
    this.notify();
  }
}

export const DEFAULT_FIELDS = ['Nome', 'Idade', 'Raça / espécie', 'Classe / profissão', 'Aparência', 'Personalidade', 'História', 'Objetivos', 'Atributos', 'Inventário'];

-- RPG Hub: esquema inicial para Supabase.
-- Execute este arquivo inteiro no SQL Editor do seu projeto.

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 24),
  avatar text not null default ''
);

create table if not exists public.campaigns (
  id uuid primary key default gen_random_uuid(),
  gm_id uuid not null references public.profiles(id) on delete cascade,
  invite_code text not null unique check (invite_code ~ '^[A-HJ-NP-Z2-9]{6}$'),
  members uuid[] not null default '{}',
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint campaigns_gm_is_member check (gm_id = any(members))
);

create index if not exists campaigns_members_gin on public.campaigns using gin (members);
create index if not exists campaigns_created_at_idx on public.campaigns (created_at desc);

alter table public.profiles enable row level security;
alter table public.campaigns enable row level security;

drop policy if exists "Signed-in users can read player profiles" on public.profiles;
create policy "Signed-in users can read player profiles"
  on public.profiles for select to authenticated
  using (auth.uid() is not null);

drop policy if exists "Players can create their own profile" on public.profiles;
create policy "Players can create their own profile"
  on public.profiles for insert to authenticated
  with check (id = auth.uid());

drop policy if exists "Players can update their own profile" on public.profiles;
create policy "Players can update their own profile"
  on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());

drop policy if exists "Campaign members can read their campaigns" on public.campaigns;
create policy "Campaign members can read their campaigns"
  on public.campaigns for select to authenticated
  using (auth.uid() = any(members));

drop policy if exists "Players can create campaigns as their own GM" on public.campaigns;
create policy "Players can create campaigns as their own GM"
  on public.campaigns for insert to authenticated
  with check (gm_id = auth.uid() and auth.uid() = any(members));

drop policy if exists "Only the GM can delete a campaign" on public.campaigns;
create policy "Only the GM can delete a campaign"
  on public.campaigns for delete to authenticated
  using (gm_id = auth.uid());

create or replace function public.rpg_join_campaign(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_campaign public.campaigns%rowtype;
begin
  if auth.uid() is null then
    raise exception 'É necessário entrar para participar de uma campanha.';
  end if;
  if not exists (select 1 from public.profiles where id = auth.uid()) then
    raise exception 'Crie seu perfil antes de entrar em uma campanha.';
  end if;

  select * into v_campaign
  from public.campaigns
  where invite_code = upper(trim(p_code))
  for update;

  if not found then
    raise exception 'Código não encontrado.';
  end if;

  if not (auth.uid() = any(v_campaign.members)) then
    update public.campaigns
      set members = array_append(members, auth.uid())
      where id = v_campaign.id
      returning * into v_campaign;
  end if;

  return to_jsonb(v_campaign);
end;
$$;

create or replace function public.rpg_save_character(p_campaign_id uuid, p_character jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_campaign public.campaigns%rowtype;
  v_character jsonb;
  v_characters jsonb;
  v_exists boolean;
begin
  select * into v_campaign
  from public.campaigns
  where id = p_campaign_id and auth.uid() = any(members)
  for update;
  if not found then
    raise exception 'Campanha não encontrada ou acesso não permitido.';
  end if;
  if jsonb_typeof(p_character->'values') <> 'object'
    or length(trim(coalesce(p_character->'values'->>'Nome', ''))) = 0 then
    raise exception 'A ficha precisa ter um nome de personagem.';
  end if;

  v_character := jsonb_build_object(
    'id', coalesce(p_character->>'id', gen_random_uuid()::text),
    'userId', auth.uid()::text,
    'name', left(trim(p_character->'values'->>'Nome'), 80),
    'values', p_character->'values',
    'portrait', coalesce(p_character->>'portrait', '')
  );
  v_exists := exists (
    select 1 from jsonb_array_elements(coalesce(v_campaign.data->'characters', '[]'::jsonb)) item
    where item->>'userId' = auth.uid()::text
  );
  select coalesce(jsonb_agg(
    case when item->>'userId' = auth.uid()::text then v_character else item end order by ord
  ), '[]'::jsonb)
  into v_characters
  from jsonb_array_elements(coalesce(v_campaign.data->'characters', '[]'::jsonb)) with ordinality as chars(item, ord);
  if not v_exists then
    v_characters := v_characters || jsonb_build_array(v_character);
  end if;

  update public.campaigns
    set data = jsonb_set(coalesce(data, '{}'::jsonb), '{characters}', v_characters, true)
    where id = p_campaign_id
    returning * into v_campaign;
  return to_jsonb(v_campaign);
end;
$$;

create or replace function public.rpg_send_message(p_campaign_id uuid, p_message jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_campaign public.campaigns%rowtype;
  v_profile public.profiles%rowtype;
  v_character jsonb;
  v_message jsonb;
  v_text text;
  v_role text;
  v_name text;
begin
  select * into v_campaign
  from public.campaigns
  where id = p_campaign_id and auth.uid() = any(members);
  if not found then
    raise exception 'Campanha não encontrada ou acesso não permitido.';
  end if;

  v_text := trim(coalesce(p_message->>'text', ''));
  if length(v_text) = 0 or length(v_text) > 1200 then
    raise exception 'A mensagem deve ter entre 1 e 1200 caracteres.';
  end if;
  select * into v_profile from public.profiles where id = auth.uid();
  if not found then
    raise exception 'Perfil de jogador não encontrado.';
  end if;
  select item into v_character
  from jsonb_array_elements(coalesce(v_campaign.data->'characters', '[]'::jsonb)) item
  where item->>'userId' = auth.uid()::text
  limit 1;

  v_name := coalesce(nullif(v_character->>'name', ''), v_profile.name);
  v_role := case when v_campaign.gm_id = auth.uid() then 'gm' else 'player' end;
  v_message := jsonb_build_object(
    'id', gen_random_uuid(),
    'userId', auth.uid(),
    'name', v_name,
    'portrait', coalesce(v_character->>'portrait', ''),
    'role', v_role,
    'text', v_text,
    'type', case when p_message->>'type' = 'dice' then 'dice' else 'text' end,
    'time', floor(extract(epoch from clock_timestamp()) * 1000)::bigint
  );

  update public.campaigns
    set data = jsonb_set(
      coalesce(data, '{}'::jsonb),
      '{messages}',
      coalesce(data->'messages', '[]'::jsonb) || jsonb_build_array(v_message),
      true
    )
    where id = p_campaign_id;
  return v_message;
end;
$$;

revoke all on function public.rpg_join_campaign(text) from public;
revoke all on function public.rpg_save_character(uuid, jsonb) from public;
revoke all on function public.rpg_send_message(uuid, jsonb) from public;
grant execute on function public.rpg_join_campaign(text) to authenticated;
grant execute on function public.rpg_save_character(uuid, jsonb) to authenticated;
grant execute on function public.rpg_send_message(uuid, jsonb) to authenticated;

do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'campaigns'
  ) then
    alter publication supabase_realtime add table public.campaigns;
  end if;
end;
$$;

