150: function rollDice(command) {
151:   const match = command.match(/^\/(\d*)d(\d+)([+-]\d+)?$/i);
152:   if (!match) return null;
153:   const count = Number(match[1] || 1), sides = Number(match[2]), modifier = Number(match[3] || 0);
154:   if (count < 1 || count > 20 || sides < 2 || sides > 1000) return { error: 'Use de 1 a 20 dados, com lados entre 2 e 1000 (ex.: /2d6+3).' };
155:   const rolls = Array.from({ length: count }, () => Math.floor(Math.random() * sides) + 1);
156:   const total = rolls.reduce((sum, roll) => sum + roll, 0) + modifier;
157:   return { text: `🎲 ${command} → [${rolls.join(', ')}]${modifier ? ` ${modifier > 0 ? '+' : ''}${modifier}` : ''} = ${total}`, type: 'dice' };
158: }
