371: async function readImage(file) {
372:   if (!file) return '';
373:   if (!file.type.startsWith('image/')) { toast('Escolha um arquivo de imagem.'); return ''; }
374:   // Redimensiona imagens para manter os dados compactos ao sincronizá-los.
375:   const source = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); });
376:   return new Promise((resolve) => {
377:     const image = new Image();
