112:     or length(trim(coalesce(p_character->'values'->>'Nome', ''))) = 0 then
113:     raise exception 'A ficha precisa ter um nome de personagem.';
114:   end if;
115: 
116:   v_character := jsonb_build_object(
117:     'id', coalesce(p_character->>'id', gen_random_uuid()::text),
118:     'userId', auth.uid()::text,
119:     'name', left(trim(p_character->'values'->>'Nome'), 80),
120:     'values', p_character->'values',
121:     'portrait', coalesce(p_character->>'portrait', '')
122:   );
123:   v_exists := exists (
124:     select 1 from jsonb_array_elements(coalesce(v_campaign.data->'characters', '[]'::jsonb)) item
125:     where item->>'userId' = auth.uid()::text
126:   );
127:   select coalesce(jsonb_agg(
128:     case when item->>'userId' = auth.uid()::text then v_character else item end order by ord
129:   ), '[]'::jsonb)
130:   into v_characters
131:   from jsonb_array_elements(coalesce(v_campaign.data->'characters', '[]'::jsonb)) with ordinality as chars(item, ord);
132:   if not v_exists then
133:     v_characters := v_characters || jsonb_build_array(v_character);
134:   end if;
135: 
136:   update public.campaigns
137:     set data = jsonb_set(coalesce(data, '{}'::jsonb), '{characters}', v_characters, true)
138:     where id = p_campaign_id
139:     returning * into v_campaign;
140:   return to_jsonb(v_campaign);
141: end;
142: $$;
