144: create or replace function public.rpg_send_message(p_campaign_id uuid, p_message jsonb)
145: returns jsonb
146: language plpgsql
147: security definer
148: set search_path = public, pg_temp
149: as $$
150: declare
151:   v_campaign public.campaigns%rowtype;
152:   v_profile public.profiles%rowtype;
153:   v_character jsonb;
154:   v_message jsonb;
155:   v_text text;
156:   v_role text;
157:   v_name text;
