163:     raise exception 'Campanha não encontrada ou acesso não permitido.';
164:   end if;
165: 
166:   v_text := trim(coalesce(p_message->>'text', ''));
167:   if length(v_text) = 0 or length(v_text) > 1200 then
168:     raise exception 'A mensagem deve ter entre 1 e 1200 caracteres.';
169:   end if;
170:   select * into v_profile from public.profiles where id = auth.uid();
171:   if not found then
172:     raise exception 'Perfil de jogador não encontrado.';
173:   end if;
174:   select item into v_character
175:   from jsonb_array_elements(coalesce(v_campaign.data->'characters', '[]'::jsonb)) item
176:   where item->>'userId' = auth.uid()::text
177:   limit 1;
178: 
179:   v_name := coalesce(nullif(v_character->>'name', ''), v_profile.name);
180:   v_role := case when v_campaign.gm_id = auth.uid() then 'gm' else 'player' end;
181:   v_message := jsonb_build_object(
182:     'id', gen_random_uuid(),
183:     'userId', auth.uid(),
184:     'name', v_name,
185:     'portrait', coalesce(v_character->>'portrait', ''),
186:     'role', v_role,
187:     'text', v_text,
188:     'type', case when p_message->>'type' = 'dice' then 'dice' else 'text' end,
189:     'time', floor(extract(epoch from clock_timestamp()) * 1000)::bigint
190:   );
191: 
192:   update public.campaigns
193:     set data = jsonb_set(
194:       coalesce(data, '{}'::jsonb),
195:       '{messages}',
196:       coalesce(data->'messages', '[]'::jsonb) || jsonb_build_array(v_message),
197:       true
198:     )
199:     where id = p_campaign_id;
